.form-icon {
  inline-size: 16px;
  block-size: 16px;

  input:is(:user-invalid, :invalid) ~ & {
    display: none;
  }

  &.input-warning,
  &.input-success {
    position: absolute;
    inset-inline-end: 0;
    padding-inline-end: 10px;

    .number-input ~ & {
      padding-inline-end: 30px;
    }
  }
}

.notification-bar {
  padding: 6px 12px;
  margin-block-start: var(--hub-notification-bar-margin-block-start);
  margin-inline: auto;
  inline-size: var(--hub-width);
  text-align: start;
  border: 1px solid;
  border-radius: 3px;

  &[aria-disabled="true"] {
    pointer-events: none;
  }

  &[open=""] #emailFormNotificationToggle {
    span:first-of-type {
      display: none;
    }

    span:last-of-type {
      display: flex;
    }
  }

  #emailFormNotificationToggle {
    span:first-of-type {
      display: flex;
    }

    span:last-of-type {
      display: none;
    }
  }

  .notification-title-container {
    display: flex;
    align-items: center;
    cursor: pointer;

    span {
      font-size: 1.1rem;
      padding-inline-start: 5px;
      margin-inline-start: auto;
    }

    #emailFormNotificationToggle {
      text-decoration: underline;
      white-space: nowrap;
    }

    &:has(#emailFormNotificationToggle:not([hidden])) .notification-title {
      text-align: start;
    }
  }

  .notification-title {
    font-size: 1.1rem;
    font-weight: 700;
    inline-size: 100%;
    text-align: center;
    margin-block: 0;
  }

  .notification-text {
    margin-block-start: var(--hub-notification-text-margin-block-start);
    font-size: 1rem;
    display: inline-block;
  }

  .manual-config-error-list {
    margin-block: 4px 0;
    padding-inline-start: 24px;

    & a {
      cursor: pointer;
      text-decoration: underline;
    }
  }

  .form-icon {
    margin-inline: 0 10px;
    cursor: pointer;
    display: none;
  }

  &.error .icon-danger,
  &.success .icon-success,
  &.warning .icon-warning,
  &.info .icon-info {
    display: inline-block;
